    // Improved coupling: reward bins that leave space for next item, while penalizing large gaps
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap_penalty = (post_residual - next_item_size) as f64;
            score -= (next_item_size as f64 * 4.2) + (gap_penalty * 1.35);
        } else {
            // Penalize fragmentation: higher cost if bin becomes unusable for next item
            score += 26.0;
        }
    }

    // 2. Harmonic Fragment Mitigation: Fine-tuned sliver avoidance
    // Penalize small residuals in the 1-36 range to prevent dead-space accumulation
    if post_residual > 0 && post_residual < 37 {
        score += (38.0 - post_residual as f64) * 3.8;
    }

    // 3. Scarcity & Pressure: Strategic bin reuse
    // Increase priority for remaining bins when options are limited
    if fitting_bins_count <= 3 {
        score -= (4 - fitting_bins_count) as f64 * 165.0;
    }

    // 4. Dynamic New Bin Thresholding: Adaptive Oracle
    // Tighten the cost of opening a new bin to force better utilization of current bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Increased base cost to open new bins to force consolidation
        score += 98.0 + (mean_residual * 1.25) - (progress * 85.0);
    }

    // 5. Global Density & Entropy
    // Heavier weight on fill ratio to promote consolidation
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 55.0;
    // Non-linear penalty for excessive open bin count to prevent high-entropy state
    score += (open_bins_count as f64).powf(1.2) * 11.0;

    // 6. Temporal Compaction: End-of-stream intensity
    // As the stream concludes, exponentially increase penalty for any residual space
    // Shifted start of intensification earlier to improve final packing density
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.65 {
        score += (post_residual as f64).powf(1.4) * 2.8;
    }

    score
}
